13	 * See the License for the specific language governing permissions and
14	 * limitations under the License.
15	 */
16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.util.Luhn;
20	import org.springframework.samples.petclinic.util.RegistrationDatePolicy;
21	
22	import jakarta.persistence.*;
23	import jakarta.validation.constraints.NotEmpty;
24	import jakarta.validation.constraints.Pattern;
25	
26	import java.time.LocalDate;
27	import java.util.*;
28	
29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "postcode")
49	    private String postcode;
50	
51	    @Column(name = "telephone")
52	    @NotEmpty
53	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
54	    private String telephone;
55	
56	    @Column(name = "email")
57	    private String email;
58	
59	    @Column(name = "registration_date")
60	    private LocalDate registrationDate;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @Column(name = "household_id")
66	    private String householdId;
67	
68	    @Column(name = "namesake_count")
69	    private Integer namesakeCount;
70	
71	    @Column(name = "household_size")
72	    private Integer householdSize;
73	
74	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
75	    private Set<Pet> pets;
76	
77	    /**
78	     * Resolve the registration date at creation time: default it to the server's
79	     * current date when none was supplied, and roll a weekend date forward to the
80	     * next business day so every value derived from it (such as the membership
81	     * number's year segment) uses the adjusted date.
82	     */
83	    @PrePersist
84	    private void resolveRegistrationDate() {
85	        this.registrationDate = RegistrationDatePolicy.effectiveDate(this.registrationDate);
86	    }
87	
88	    public String getAddress() {
89	        return this.address;
90	    }
91	
92	    public void setAddress(String address) {
93	        this.address = address;
94	    }
95	
96	    public String getCity() {
97	        return this.city;
98	    }
99	
100	    public void setCity(String city) {
101	        this.city = city;
102	    }
103	
104	    public String getPostcode() {
105	        return this.postcode;
106	    }
107	
108	    public void setPostcode(String postcode) {
109	        this.postcode = postcode;
110	    }
111	
112	    /**
113	     * The owner's locality: the canonical region derived by {@link Locality} from
114	     * its {@link #postcode} (preferred) and {@link #city}, or {@code "UNKNOWN"}
115	     * when neither resolves to a known region.
116	     */
117	    public String getLocality() {
118	        return Locality.of(this.city, this.postcode);
119	    }
120	
121	    public String getTelephone() {
122	        return this.telephone;
123	    }
124	
125	    public void setTelephone(String telephone) {
126	        this.telephone = telephone;
127	    }
128	
129	    public String getEmail() {
130	        return this.email;
131	    }
132	
133	    public void setEmail(String email) {
134	        this.email = email;
135	    }
136	
137	    public LocalDate getRegistrationDate() {
138	        return this.registrationDate;
139	    }
140	
141	    public void setRegistrationDate(LocalDate registrationDate) {
142	        this.registrationDate = registrationDate;
143	    }
144	
145	    public String getCustomerCode() {
146	        return this.customerCode;
147	    }
148	
149	    public void setCustomerCode(String customerCode) {
150	        this.customerCode = customerCode;
151	    }
152	
153	    /**
154	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'}
155	     * where {@code YY} is the last two digits of the {@link #registrationDate}
156	     * year (e.g. {@code "LON-SMI-0007-M26"}). Derived from the owner's own fields.
157	     */
158	    public String getMembershipNumber() {
159	        if (this.customerCode == null || this.registrationDate == null) {
160	            return null;
161	        }
162	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
163	    }
164	
165	    /**
166	     * The Luhn check digit (0-9) computed over the digits of the
167	     * {@link #customerCode}, or {@code null} when no customer code is assigned.
168	     */
169	    public Integer getCheckDigit() {
170	        if (this.customerCode == null) {
171	            return null;
172	        }
173	        return Luhn.checkDigit(this.customerCode);
174	    }
175	
176	    public String getHouseholdId() {
177	        return this.householdId;
178	    }
179	
180	    public void setHouseholdId(String householdId) {
181	        this.householdId = householdId;
182	    }
183	
184	    /**
185	     * The owner's identity key: the single derived value used to detect duplicate owners. It is the
186	     * normalized telephone, the (lower-cased) email or an empty string when absent, and the
187	     * household id or an empty string when absent, joined with {@code '|'} (e.g.
188	     * {@code "+61412345678|jo@example.com|3F2A9C1D4B6E8071"}). Two owners are the same person only
189	     * when their whole identity keys are equal; because the telephone is part of the key, household
190	     * members with different telephones have different keys.
191	     */
192	    public String getIdentityKey() {
193	        return String.join("|",
194	            this.telephone == null ? "" : this.telephone,
195	            this.email == null ? "" : this.email,
196	            this.householdId == null ? "" : this.householdId);
197	    }
198	
199	    /**
200	     * The owner's membership level, a number from 1 to 3 derived from the
201	     * owner's own fields. Starts at {@code 1}, gains {@code 1} when a contact
202	     * email is on file, gains {@code 1} when the owner has no namesakes, and is
203	     * capped at {@code 3}. (Level {@code 4} is reserved for tenure.)
204	     */
205	    public Integer getMembershipLevel() {
206	        int level = 1;
207	        boolean hasEmail = this.email != null && !this.email.isEmpty();
208	        if (hasEmail) {
209	            level += 1;
210	        }
211	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
212	        if (noNamesakes) {
213	            level += 1;
214	        }
215	        return Math.min(level, 3);
216	    }
217	
218	    /**
219	     * The owner's preferred contact channel, derived from the fields on file:
220	     * {@code "EMAIL"} when a contact email is present, otherwise {@code "PHONE"}.
221	     */
222	    public String getContactPreference() {
223	        boolean hasEmail = this.email != null && !this.email.isEmpty();
224	        return hasEmail ? "EMAIL" : "PHONE";
225	    }
226	
227	    public Integer getNamesakeCount() {
228	        return this.namesakeCount;
229	    }
230	
231	    public void setNamesakeCount(Integer namesakeCount) {
232	        this.namesakeCount = namesakeCount;
233	    }
234	
235	    public Integer getHouseholdSize() {
236	        return this.householdSize;
237	    }
238	
239	    public void setHouseholdSize(Integer householdSize) {
240	        this.householdSize = householdSize;
241	    }
242	
243	    protected Set<Pet> getPetsInternal() {
244	        if (this.pets == null) {
245	            this.pets = new HashSet<>();
246	        }
247	        return this.pets;
248	    }
249	
250	    protected void setPetsInternal(Set<Pet> pets) {
251	        this.pets = pets;
252	    }
253	
254	    public List<Pet> getPets() {
255	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
256	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
257	        return Collections.unmodifiableList(sortedPets);
258	    }
259	
260	    public void setPets(List<Pet> pets) {
261	        this.pets = new HashSet<>(pets);
262	    }
263	
264	    public void addPet(Pet pet) {
265	        getPetsInternal().add(pet);
266	        pet.setOwner(this);
267	    }
268	
269	    /**
270	     * Return the Pet with the given name, or null if none found for this Owner.
271	     *
272	     * @param name to test
273	     * @return true if pet name is already in use
274	     */
275	    public Pet getPet(String name) {
276	        return getPet(name, false);
277	    }
278	
279	    /**
280	     * Return the Pet with the given name, or null if none found for this Owner.
281	     *
282	     * @param name to test
283	     * @return true if pet name is already in use
284	     */
285	    public Pet getPet(String name, boolean ignoreNew) {
286	        name = name.toLowerCase();
287	        for (Pet pet : getPetsInternal()) {
288	            if (!ignoreNew || !pet.isNew()) {
289	                String compName = pet.getName();
290	                compName = compName.toLowerCase();
291	                if (compName.equals(name)) {
292	                    return pet;
293	                }
294	            }
295	        }
