18	
19	import java.util.Map;
20	import java.util.regex.Pattern;
21	
22	/**
23	 * Normalizes an owner's telephone number to canonical E.164 form. A leading {@code '+'} and its
24	 * country code are preserved when present; otherwise the default country code {@code +61} is
25	 * assumed and a single leading {@code '0'} is dropped from the national digits. Separators such as
26	 * spaces, dashes and brackets are stripped. The result must carry 8 to 15 digits after the
27	 * {@code '+'}, and for a recognised country code the national number must be exactly as long as
28	 * that country requires ({@code +61} => 9 national digits, {@code +1} => 10). A number that cannot
29	 * form a valid E.164 value is rejected.
30	 */
31	public final class TelephoneNormalizer {
32	
33	    private static final Pattern NON_DIGIT = Pattern.compile("\\D");
34	
35	    private static final String DEFAULT_COUNTRY_CODE = "61";
36	
37	    private static final int MIN_DIGITS = 8;
38	
39	    private static final int MAX_DIGITS = 15;
40	
41	    /** Recognised country codes (the digits after {@code '+'}) mapped to their required national-number length. */
42	    private static final Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY = Map.of(
43	            "61", 9,
44	            "1", 10);
45	
46	    private TelephoneNormalizer() {
47	    }
48	
49	    /**
50	     * Converts the supplied telephone to its canonical E.164 representation.
51	     *
52	     * @param telephone the raw telephone as submitted
53	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
54	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
55	     */
56	    public static String normalize(String telephone) {
57	        String trimmed = telephone == null ? "" : telephone.trim();
58	        boolean hasCountryCode = trimmed.startsWith("+");
59	        String digits = NON_DIGIT.matcher(trimmed).replaceAll("");
60	
61	        String countryCode;
62	        String national;
63	        if (hasCountryCode) {
64	            countryCode = recognisedCountryCode(digits);
65	            national = countryCode == null ? digits : digits.substring(countryCode.length());
66	        } else {
67	            countryCode = DEFAULT_COUNTRY_CODE;
68	            national = digits.startsWith("0") ? digits.substring(1) : digits;
69	        }
70	
71	        String e164 = "+" + (countryCode == null ? digits : countryCode + national);
72	
73	        int digitCount = e164.length() - 1;
74	        if (digitCount < MIN_DIGITS || digitCount > MAX_DIGITS) {
75	            throw new InvalidTelephoneException(telephone);
76	        }
77	        Integer requiredNationalLength = countryCode == null ? null : NATIONAL_LENGTH_BY_COUNTRY.get(countryCode);
78	        if (requiredNationalLength != null && national.length() != requiredNationalLength) {
79	            throw new InvalidTelephoneException(telephone);
80	        }
81	        return e164;
82	    }
83	
84	    /**
85	     * Returns the recognised country code that the given digit string begins with, or {@code null}
86	     * when no known country code matches. Longer codes are preferred so a specific match wins over
87	     * a shorter prefix.
88	     */
89	    private static String recognisedCountryCode(String digits) {
90	        String match = null;
91	        for (String code : NATIONAL_LENGTH_BY_COUNTRY.keySet()) {
92	            if (digits.startsWith(code) && (match == null || code.length() > match.length())) {
93	                match = code;
94	            }
95	        }
96	        return match;
97	    }
98	}
